function daftarBahasa(){return [...BAHASA_DIDUKUNG];}
function tambahBahasa(kode,paket){const k=String(kode).toLowerCase().trim();const wajib=["satuan","huruf","kode","op_gabung","bulan","bulan_singkat","kata_min","kata_koma","kata_titik","kata_koma_baca","kata_persen","kata_permil","kata_kali","kata_pangkat","kata_per","ordinal_pola"];const kurang=wajib.filter(x=>!(x in paket));if(kurang.length)throw new CikurGoError(`Paket bahasa kurang kunci: ${kurang.join(", ")}`, "INVALID_LANGUAGE");REG_BHS[k]=paket;if(!BAHASA_DIDUKUNG.includes(k))BAHASA_DIDUKUNG.push(k);}
