 if (warnaMatch.length) { hipotesis.push({ jenis: "warna", bobot: 0.9, detail: warnaMatch }); alasan.push(`Warna/hex: ${warnaMatch.join(", ")}`); }
 if (arabMatch) { hipotesis.push({ jenis: "script_arab", bobot: 0.95 }); alasan.push("Karakter Arab terdeteksi"); }
